function model(p) {
  // One health claim moves across five desks (lanes): the member, intake, adjudication, payment and appeals.
  // Every event is either work at a desk or a wait between desks; the elapsed time is the sum of both.
  // Durations are illustrative business days for a fictional plan, not a benchmark.
  const manual = Math.round(p.route) === 1;
  const reviewers = Math.max(1, Math.min(5, Math.round(p.reviewers)));
  const outcome = Math.max(0, Math.min(2, Math.round(p.outcome))); // 0 approved, 1 denied, 2 denied then appealed
  const lanes = [
    { id: 'member', label: 'Member', icon: 'user' },
    { id: 'intake', label: 'Intake', icon: 'inbox' },
    { id: 'adjud', label: 'Adjudication', icon: 'scale' },
    { id: 'payment', label: 'Payment', icon: 'banknote' },
    { id: 'appeals', label: 'Appeals', icon: 'gavel' }
  ];
  const events = [];
  let t = 0;
  const work = (lane, label, dur, note, extra) => { events.push(Object.assign({ i: events.length, lane, kind: 'work', label, start: +t.toFixed(2), dur, note }, extra || {})); t += dur; };
  const wait = (lane, label, dur, note) => { if (dur <= 0) return; events.push({ i: events.length, lane, kind: 'wait', label, start: +t.toFixed(2), dur, note }); t += dur; };
  const queueWait = +(5 / reviewers).toFixed(1); // a backlog of pending claims shared by the reviewers on duty
  work('member', 'Visit and claim', 1, 'The member sees a provider; the provider submits the claim by the next day.');
  work('intake', 'Receive and validate', 1, 'Intake loads the claim, checks member and provider identifiers and the codes; the edits pass.');
  wait('intake', 'Nightly batch', 0.5, 'The claim waits for the nightly batch that hands validated claims to adjudication.');
  if (!manual) work('adjud', 'Auto-adjudicated', 0.2, 'The rules engine prices the claim against the benefit and the contract in minutes.', { auto: true });
  else {
    wait('adjud', 'Pending queue', queueWait, 'The claim pends for a reviewer: ' + reviewers + (reviewers === 1 ? ' reviewer clears' : ' reviewers clear') + ' the shared backlog, so the wait is about ' + queueWait + ' days.');
    work('adjud', 'Manual review', 1, 'A reviewer checks medical necessity and the documentation and decides.');
  }
  const denied = outcome > 0;
  if (!denied) {
    wait('payment', 'Payment cycle', 3, 'Approved claims wait for the weekly payment run.');
    work('payment', 'Pay and remit', 1, 'The payment run pays the provider and issues the explanation of benefits.');
    wait('member', 'Mail', 2, 'The explanation of benefits is printed and mailed.');
    work('member', 'EOB received', 0.5, 'The member reads what was paid and what they owe.');
  } else {
    wait('member', 'Mail', 2, 'The denial letter is printed and mailed.');
    work('member', 'Denial letter', 0.5, 'The member reads the denial and the reason code.', { bad: true });
    if (outcome === 2) {
      work('member', 'File appeal', 2, 'The member gathers records from the provider and files an appeal.');
      wait('appeals', 'Appeals queue', 5, 'The appeal waits its turn with a clinical reviewer.');
      work('appeals', 'Appeal review', 6, 'A clinical reviewer re-examines the claim with the new records and overturns the denial.');
      wait('payment', 'Payment cycle', 3, 'The overturned claim waits for the next weekly payment run.');
      work('payment', 'Pay and remit', 1, 'The payment run pays the provider and issues a corrected explanation of benefits.');
      wait('member', 'Mail', 2, 'The corrected explanation of benefits is mailed.');
      work('member', 'EOB received', 0.5, 'The member finally sees the claim paid.');
    }
  }
  const elapsed = +t.toFixed(2);
  const touch = +events.filter(e => e.kind === 'work').reduce((a, e) => a + e.dur, 0).toFixed(2);
  const waiting = +events.filter(e => e.kind === 'wait').reduce((a, e) => a + e.dur, 0).toFixed(2);
  const handoffs = events.filter((e, i) => i > 0 && e.lane !== events[i - 1].lane).length;
  const paid = !denied || outcome === 2;
  const lanesUsed = lanes.filter(l => events.some(e => e.lane === l.id)).map(l => l.id);
  // Playback: the clock runs over the whole elapsed time; each event is a scene
  const duration = 24, scale = duration / elapsed;
  events.forEach(e => { e.at = +(e.start * scale).toFixed(3); e.len = +(e.dur * scale).toFixed(3); e.end = +(e.start + e.dur).toFixed(2); });
  const fmtD = d => (Math.round(d * 10) / 10) + (d === 1 ? ' day' : ' days');
  const summary = (paid ? 'Paid after ' : 'Denied after ') + fmtD(elapsed) + ': ' + fmtD(touch) + ' of work at the desks, ' + fmtD(waiting) + ' of waiting, ' + handoffs + ' hand-offs' + (outcome === 2 ? ', one appeal.' : '.');
  return {
    lanes, lanesUsed, events, manual, reviewers, outcome, paid, denied,
    totals: { elapsed, touch, waiting, handoffs, touchShare: Math.round(100 * touch / elapsed) },
    duration, markers: events.map(e => e.at), summary
  };
}

