function check(p) {
  const m = model(p), T = m.totals, round = v => Math.round(v * 100) / 100;
  // Events are back to back: each starts when the previous ends, and the elapsed time is work plus waiting
  const sequential = m.events.every((e, i) => i === 0 || round(e.start) === round(m.events[i - 1].start + m.events[i - 1].dur));
  const sums = round(T.touch + T.waiting) === round(T.elapsed);
  // The lanes used follow the route and the outcome
  const appealsUsed = m.lanesUsed.includes('appeals'), paymentUsed = m.lanesUsed.includes('payment');
  const lanesOk = appealsUsed === (m.outcome === 2) && paymentUsed === m.paid;
  // Manual review adds a pending wait that shrinks with reviewers; auto-adjudication has none
  const pend = m.events.find(e => e.label === 'Pending queue');
  const routeOk = m.manual ? (!!pend && Math.abs(pend.dur - 5 / m.reviewers) < 0.11) : !pend;
  // Playback markers are in order and inside the duration
  const markersOk = m.markers.every((v, i) => i === 0 || v > m.markers[i - 1]) && m.markers[m.markers.length - 1] < m.duration;
  const pass = sequential && sums && lanesOk && routeOk && markersOk;
  return {
    pass,
    detail: T.elapsed + ' days elapsed = ' + T.touch + ' days of work + ' + T.waiting + ' days of waiting' + (sums ? '' : ' (does not add up)') + '; ' + m.events.length + ' events back to back' + (sequential ? '' : ' (gap or overlap)') +
      '; lanes used: ' + m.lanesUsed.join(', ') + (lanesOk ? '' : ' (wrong for this outcome)') + '; ' + (m.manual ? 'pending ' + (pend ? pend.dur : '?') + ' days for ' + m.reviewers + ' reviewer(s)' : 'auto-adjudicated, no pending queue') + (routeOk ? '.' : ' (wrong).')
  };
}
